public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size++;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            i++;
            char low = str.charAt(i);
            if (Character.isLowSurrogate(low)) {
                size += 4;
            } else {
                size += 3;
            }
        } else {
            size += 3;
        }
    }
    return size;
}

