public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity >= 1000) {
        // If the desired capacity is greater than or equal to 1000,
        // we want to make sure that the returned prime number is within 11% of the desired capacity.
        // To do this, we first find the next prime number that is greater than or equal to the desired capacity.
        // Then, we check if the difference between the desired capacity and the returned prime number is within 11%.
        // If it is, we return the prime number. Otherwise, we continue searching for a prime number that meets the criteria.
        for (int i = desiredCapacity; i < Integer.MAX_VALUE; i++) {
            if (isPrime(i)) {
                int diff = Math.abs(i - desiredCapacity);
                if (diff <= (int) (0.11 * desiredCapacity)) {
                    return i;
                }
            }
        }
    } else {
        // If the desired capacity is less than 1000, we can simply return the next prime number that is greater than or equal to the desired capacity.
        for (int i = desiredCapacity; i < Integer.MAX_VALUE; i++) {
            if (isPrime(i)) {
                return i;
            }
        }
    }
    // If no prime number was found that meets the criteria, we return the maximum value of an integer.
    return Integer.MAX_VALUE;
}

