public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder(str.length());
    int pos = 0;
    while (pos < str.length()) {
        char ch = str.charAt(pos);
        if (ch == '\\') {
            pos++;
            ch = str.charAt(pos);
            switch (ch) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '0':
                    sb.append((char) 0);
                    break;
                case 'u':
                    pos++;
                    int code = Integer.parseInt(str.substring(pos, pos + 4), 16);
                    sb.append((char) code);
                    pos += 4;
                    break;
                default:
                    throw new Exception("Illegal escape character: " + ch);
            }
        } else {
            sb.append(ch);
        }
        pos++;
    }
    return sb.toString();
}

