public int addConstantNameAndType(String name, String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 1; i < constantPool.size(); i++) {
        ConstantInfo info = constantPool.get(i);
        if (info instanceof ConstantNameAndType) {
            ConstantNameAndType nameAndType = (ConstantNameAndType) info;
            if (nameAndType.getName().equals(name) && nameAndType.getDescriptor().equals(descriptor)) {
                return i;
            }
        }
    }

    // If not, create a new ConstantNameAndType and add it to the constant pool
    ConstantNameAndType nameAndType = new ConstantNameAndType(name, descriptor);
    constantPool.add(nameAndType);
    return constantPool.size() - 1;
}

