    for (E e : graph.edgeSet()) {
        List<Pair<Integer, Integer>> minimalSeparators = new ArrayList<>();
        for (V v : graph.neighborListOf(e.getFirst())) {
            if (v.equals(e.getSecond())) {
                continue;
            }
